SELECT CASE WHEN
    EXISTS (
        SELECT 1
        FROM attendance
        WHERE school_id = #{schoolId}
          AND session_id = #{sessionId}
    )
    OR EXISTS (
        SELECT 1
        FROM schedule_adjustment
        WHERE school_id = #{schoolId}
          AND session_id = #{sessionId}
    )
    OR EXISTS (
        SELECT 1
        FROM leave_request
        WHERE school_id = #{schoolId}
          AND session_id = #{sessionId}
    )
    OR EXISTS (
        SELECT 1
        FROM supervision_alert
        WHERE school_id = #{schoolId}
          AND session_id = #{sessionId}
    )
THEN 1 ELSE 0 END

