FROM attendance
WHERE session_id = #{sessionId}

SELECT conflicts.id
FROM (
    SELECT ls.id
    FROM lesson_session ls
    JOIN course_offering o ON o.id = ls.offering_id
    WHERE o.teacher_id = #{teacherId}
      AND ls.id != #{excludeSessionId}
      AND ls.session_date = #{sessionDate}
      AND ls.start_time < #{endTime}
      AND ls.end_time > #{startTime}
      AND ls.status != 'CANCELED'
      AND o.status NOT IN ('CANCELED', 'FINISHED')
    UNION ALL
    SELECT o.id
    FROM course_offering o
    WHERE o.teacher_id = #{teacherId}
      AND o.id != (
          SELECT current_session.offering_id
          FROM lesson_session current_session
          WHERE current_session.id = #{excludeSessionId}
      )
      AND o.week_day = WEEKDAY(#{sessionDate}) + 1
      AND o.start_date <= #{sessionDate}
      AND o.end_date >= #{sessionDate}
      AND o.start_time < #{endTime}
      AND o.end_time > #{startTime}
      AND o.status NOT IN ('CANCELED', 'FINISHED')
      AND NOT EXISTS (
          SELECT 1
          FROM lesson_session generated_session
          WHERE generated_session.offering_id = o.id
            AND generated_session.session_date = #{sessionDate}
      )
      AND NOT EXISTS (
          SELECT 1
          FROM schedule_adjustment moved_adjustment
          JOIN lesson_session moved_session
            ON moved_session.id = moved_adjustment.session_id
          WHERE moved_session.offering_id = o.id
            AND moved_adjustment.original_session_date = #{sessionDate}
            AND moved_adjustment.status = 'APPLIED'
      )
) conflicts
ORDER BY conflicts.id
LIMIT 1

SELECT conflicts.id
FROM (
    SELECT ls.id
    FROM lesson_session ls
    JOIN course_offering o ON o.id = ls.offering_id
    WHERE ls.school_id = #{schoolId}
      AND COALESCE(ls.room_id, o.room_id) = #{roomId}
      AND ls.id != #{excludeSessionId}
      AND ls.session_date = #{sessionDate}
      AND ls.start_time < #{endTime}
      AND ls.end_time > #{startTime}
      AND ls.status != 'CANCELED'
      AND o.status NOT IN ('CANCELED', 'FINISHED')
    UNION ALL
    SELECT o.id
    FROM course_offering o
    WHERE o.school_id = #{schoolId}
      AND o.room_id = #{roomId}
      AND o.id != (
          SELECT current_session.offering_id
          FROM lesson_session current_session
          WHERE current_session.id = #{excludeSessionId}
      )
      AND o.week_day = WEEKDAY(#{sessionDate}) + 1
      AND o.start_date <= #{sessionDate}
      AND o.end_date >= #{sessionDate}
      AND o.start_time < #{endTime}
      AND o.end_time > #{startTime}
      AND o.status NOT IN ('CANCELED', 'FINISHED')
      AND NOT EXISTS (
          SELECT 1
          FROM lesson_session generated_session
          WHERE generated_session.offering_id = o.id
            AND generated_session.session_date = #{sessionDate}
      )
      AND NOT EXISTS (
          SELECT 1
          FROM schedule_adjustment moved_adjustment
          JOIN lesson_session moved_session
            ON moved_session.id = moved_adjustment.session_id
          WHERE moved_session.offering_id = o.id
            AND moved_adjustment.original_session_date = #{sessionDate}
            AND moved_adjustment.status = 'APPLIED'
      )
) conflicts
ORDER BY conflicts.id
LIMIT 1

SELECT conflicts.id
FROM (
    /* Existing effective sessions include adjusted date/time values
       written to lesson_session by an earlier reschedule. */
    SELECT existing_session.id
    FROM enrollment e
    JOIN course_offering existing ON existing.id = e.offering_id
    JOIN lesson_session existing_session
      ON existing_session.offering_id = existing.id
    WHERE e.student_id = #{studentId}
      AND e.status = 'ENROLLED'
      AND existing.id != #{offeringId}
      AND existing.status NOT IN ('CANCELED', 'FINISHED')
      AND existing_session.status != 'CANCELED'
      AND existing_session.session_date = #{sessionDate}
      AND existing_session.start_time < #{endTime}
      AND existing_session.end_time > #{startTime}
    UNION ALL
    /* A course without an effective generated lesson retains the
       offering template as a conflict guard. */
    SELECT existing.id
    FROM enrollment e
    JOIN course_offering existing ON existing.id = e.offering_id
    WHERE e.student_id = #{studentId}
      AND e.status = 'ENROLLED'
      AND existing.id != #{offeringId}
      AND existing.status NOT IN ('CANCELED', 'FINISHED')
      AND NOT EXISTS (
          SELECT 1
          FROM lesson_session existing_session
          WHERE existing_session.offering_id = existing.id
            AND existing_session.status != 'CANCELED'
      )
      AND existing.week_day = WEEKDAY(#{sessionDate}) + 1
      AND existing.start_date <= #{sessionDate}
      AND existing.end_date >= #{sessionDate}
      AND existing.start_time < #{endTime}
      AND existing.end_time > #{startTime}
) conflicts
ORDER BY conflicts.id
LIMIT 1

mapper.update:
UPDATE lesson_session
SET session_date = #{sessionDate},
    start_time = #{startTime},
    end_time = #{endTime},
    room_id = #{roomId},
    classroom = #{classroom}
WHERE id = #{sessionId}
  AND school_id = #{schoolId}
  AND status = 'SCHEDULED'

UPDATE schedule_adjustment
SET status = 'REVERTED'
WHERE id = #{adjustmentId}
  AND school_id = #{schoolId}
  AND status = 'APPLIED'

mapper.select:
SELECT id
FROM course_offering
WHERE school_id = #{schoolId}
  AND room_id = #{roomId}
  AND id != #{excludeOfferingId}
  AND week_day = #{weekDay}
  AND start_date <= #{endDate}
  AND end_date >= #{startDate}
  AND start_time < #{endTime}
  AND end_time > #{startTime}
  AND status NOT IN ('CANCELED', 'FINISHED')
ORDER BY id
LIMIT 1
FOR UPDATE
